            pl={{ base: 0, lg: 0 }}
            w={{ base: "100%", lg: "50%" }}
            h={{ base: "auto", lg: "100%" }}
            display="flex"
            flexDirection="column"
            justifyContent={{ base: "flex-start", lg: "center" }}
            alignItems={{ base: "center", lg: "flex-start" }}
            textAlign={{ base: "center", lg: "left" }}
            pt={{ base: 8, lg: 0 }}
            pb={{ base: 4, lg: 0 }}
            px={{ base: 4, lg: 4 }}
          >
            <Text
              fontSize={{ base: "2xl", md: "3xl", lg: "4xl" }}
              mb={4}
              fontWeight={500}
              lineHeight={1.1}
              pl={{ base: 0, lg: '6rem' }}
            >
              Card stacks have never{" "}
              <Box as="span" display={{ base: "inline", lg: "block" }}>
                looked so good
              </Box>
            </Text>
            <Text
              fontSize={{ base: "lg", lg: "xl" }}
              mb={4}
              fontWeight={400}
              lineHeight={1.1}
              color="#999"
              pl={{ base: 0, lg: '6rem' }}
            >
              Just look at it go!
            </Text>
          </Box>
          <Box
            w={{ base: "100%", lg: "50%" }}
            h={{ base: "400px", lg: "100%" }}
            position="relative"
          >
            <CardSwap
              key={key}
              cardDistance={cardDistance}
              verticalDistance={verticalDistance}
              delay={delay}
              skewAmount={skewAmount}
              easing={easing}
              pauseOnHover={pauseOnHover}
