      <CodeTab>
        <CodeExample codeObject={cardSwap} />
      </CodeTab>

      <CliTab>
        <CliInstallation {...cardSwap} />
      </CliTab>
    </TabbedLayout>
  );
};

export default CardSwapDemo;

