            gap={gap}
            borderRadius={10}
            horizontalPadding={15}
            textColor="white"
            fontWeight={900}
          />

          <Flex gap={4} bottom="1em" direction={"row"} justify={"center"} mt={4} position='absolute'>
            <Button
              bg="#170D27"
              borderRadius="10px"
              border="1px solid #271E37"
              _hover={{ bg: "#271E37" }}
              color="#fff"
              h={10}
              w={10}
              onClick={() => setValue(value - 1)}>
              -
            </Button>
            <Button
              bg="#170D27"
              borderRadius="10px"
              border="1px solid #271E37"
              _hover={{ bg: "#271E37" }}
              color="#fff"
              h={10}
              w={10}
