            value={gap}
            onChange={(val) => setGap(val)}
          />

          <PreviewSlider
            title="Font Size"
            min={40}
            max={200}
            step={10}
            value={fontSize}
            onChange={(val) => setFontSize(val)}
          />
        </Customize>

        <PropTable data={propData} />
        <Dependencies dependencyList={['framer-motion']} />
      </PreviewTab>

      <CodeTab>
        <CodeExample codeObject={counter} />
      </CodeTab>

      <CliTab>
        <CliInstallation {...counter} />
      </CliTab>
    </TabbedLayout>
  );
};

export default CounterDemo;

