            title="Plane Width"
            min={300}
            max={400}
            step={10}
            value={planeWidth}
            onChange={(val) => {
              setPlaneWidth(val);
              forceRerender();
            }}
            displayValue={(val) => `${val}px`}
          />

          <PreviewSlider
            title="Plane Height"
            min={200}
            max={350}
            step={10}
            value={planeHeight}
            onChange={(val) => {
              setPlaneHeight(val);
              forceRerender();
            }}
            displayValue={(val) => `${val}px`}
          />

          <PreviewSlider
            title="Distortion"
            min={0}
            max={10}
            step={0.1}
            value={distortion}
            onChange={(val) => {
              setDistortion(val);
              forceRerender();
            }}
            displayValue={(val) => val.toFixed(1)}
          />

          <PreviewSlider
            title="Scroll Ease"
            min={0.001}
            max={0.05}
            step={0.001}
            value={scrollEase}
            onChange={(val) => {
              setScrollEase(val);
              forceRerender();
            }}
            displayValue={(val) => val.toFixed(3)}
          />

          <PreviewSlider
            title="Camera FOV"
            min={20}
            max={90}
            step={1}
            value={cameraFov}
            onChange={(val) => {
              setCameraFov(val);
              forceRerender();
            }}
            displayValue={(val) => `${val}°`}
          />

          <PreviewSlider
            title="Camera Z"
            min={5}
            max={50}
            step={1}
            value={cameraZ}
            onChange={(val) => {
              setCameraZ(val);
              forceRerender();
            }}
          />
        </Customize>

        <PropTable data={propData} />
        <Dependencies dependencyList={["ogl"]} />
      </PreviewTab>

      <CodeTab>
        <CodeExample codeObject={flyingPosters} />
      </CodeTab>

      <CliTab>
        <CliInstallation {...flyingPosters} />
      </CliTab>
    </TabbedLayout>
  );
};

export default FlyingPostersDemo;

