            step={1}
            value={particleCount}
            onChange={(val) => {
              setParticleCount(val);
            }}
          />

          <PreviewSlider
            title="Animation Variance"
            min={0}
            max={2000}
            step={100}
            value={timeVariance}
            onChange={(val) => {
              setTimeVariance(val);
            }}
          />

          <PreviewSlider
            title="Radius Factor"
            min={0}
            max={1000}
            step={100}
            value={particleR}
            onChange={(val) => {
              setParticleR(val);
            }}
          />
        </Customize>

        <PropTable data={propData} />
      </PreviewTab>

      <CodeTab>
        <CodeExample codeObject={gooeyNav} />
      </CodeTab>

      <CliTab>
        <CliInstallation {...gooeyNav} />
      </CliTab>
    </TabbedLayout>
  );
};

