          />

          <PreviewSlider
            title="Duration"
            min={0.1}
            max={2.0}
            step={0.1}
            value={duration}
            valueUnit="s"
            width={150}
            onChange={setDuration}
          />

          <PreviewSlider
            title="Stagger"
            min={0.01}
            max={0.2}
            step={0.01}
            value={stagger}
            valueUnit="s"
            width={150}
            onChange={setStagger}
          />

          <PreviewSwitch
            title="Scale on Hover"
            isChecked={scaleOnHover}
            onChange={setScaleOnHover}
          />

          <PreviewSwitch
            title="Blur to Focus"
            isChecked={blurToFocus}
            onChange={setBlurToFocus}
          />

          <PreviewSwitch
            title="Color Shift on Hover"
            isChecked={colorShiftOnHover}
