      </PreviewTab>

      <CodeTab>
        <CodeExample codeObject={masonry} />
      </CodeTab>

      <CliTab>
        <CliInstallation {...masonry} />
      </CliTab>
    </TabbedLayout>
  );
};

export default MasonryDemo;

